  `reset_password_expires_at` datetime DEFAULT NULL,
  `is_available` tinyint(1) DEFAULT 1,
  `last_activity` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
